@push('scripts')<script>
(()=>{const video=document.getElementById('scannerVideo'),start=document.getElementById('startScanner'),stop=document.getElementById('stopScanner'),msg=document.getElementById('scannerMessage');let stream=null,active=false,detector=null;const shutdown=()=>{active=false;stream?.getTracks().forEach(t=>t.stop());stream=null;video.srcObject=null;start.disabled=false;stop.disabled=true;};stop.addEventListener('click',shutdown);start.addEventListener('click',async()=>{if(!('BarcodeDetector' in window)){msg.textContent='This browser does not support native QR scanning. Use the asset tag search field or a USB barcode scanner.';return;}try{detector=new BarcodeDetector({formats:['qr_code','code_128','code_39','ean_13']});stream=await navigator.mediaDevices.getUserMedia({video:{facingMode:{ideal:'environment'}},audio:false});video.srcObject=stream;await video.play();active=true;start.disabled=true;stop.disabled=false;msg.textContent='Camera active. Point it at an asset label.';const scan=async()=>{if(!active)return;try{const codes=await detector.detect(video);if(codes.length){const value=codes[0].rawValue;if(value.startsWith(location.origin)){location.href=value;return;}location.href='{{ route('scan.index') }}?tag='+encodeURIComponent(value);return;}}catch(e){}requestAnimationFrame(scan);};scan();}catch(e){msg.textContent='Camera could not be started: '+e.message;shutdown();}});window.addEventListener('pagehide',shutdown);})();
</script>@endpush
